class _SecurityViewState extends ConsumerState<SecurityView> {
  bool _lock = false;

  Future<void> _duressToggled(bool newValue) async {
    if (_lock) return;
    try {
      _lock = true;

      if (newValue) {
        await _createDuressPin();
      } else {
        await _deleteDuressPin();
      }
    } finally {
      _lock = false;
    }
  }

  Future<void> _createDuressPin() async {
    final result = await showDialog<bool>(
      context: context,
      builder: (context) => StackDialogBase(
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              S.of(context)!.enableDuressPIN,
              style: STextStyles.pageTitleH2(context),
            ),
            const SizedBox(height: 8),
            Row(
              children: [
                Flexible(
                  child: Text(
                    S.of(context)!.duressPinExplanation,
                    style: STextStyles.smallMed14(context),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 20),
            Row(
              children: [
                Expanded(
                  child: SecondaryButton(
                    label: S.of(context)!.cancel,
                    onPressed: () => Navigator.of(context).pop(false),
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: PrimaryButton(
                    label: S.of(context)!.ok,
                    onPressed: () => Navigator.of(context).pop(true),
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );

    if (result == true && mounted) {
      await Navigator.push(
        context,
        RouteGenerator.getRoute(
          shouldUseMaterialRoute: RouteGenerator.useMaterialPageRoute,
          builder: (_) => LockscreenView(
            showBackButton: true,
            routeOnSuccess: CreateDuressPinView.routeName,
            biometricsCancelButtonString: S.of(context)!.cancel,
            biometricsLocalizedReason: S.of(context)!.authToCreateDuressPIN,
            biometricsAuthenticationTitle: S.of(context)!.createDuressPIN,
          ),
          settings: const RouteSettings(name: "/createDuressPinLockscreen"),
        ),
      );
    }
  }

  Future<void> _deleteDuressPin() async {
    await showDialog<void>(
      context: context,
      builder: (context) => StackDialogBase(
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(
              S.of(context)!.disableDuressPIN,
              style: STextStyles.pageTitleH2(context),
            ),
            const SizedBox(height: 8),
            Row(
              children: [
                Flexible(
                  child: Text(
                    S.of(context)!.disableDuressPinDeleteWarning,

                    style: STextStyles.smallMed14(context),
                  ),
                ),
              ],
            ),
            const SizedBox(height: 20),
            Row(
              children: [
                Expanded(
                  child: SecondaryButton(
                    label: S.of(context)!.cancel,
                    onPressed: Navigator.of(context).pop,
                  ),
                ),
                const SizedBox(width: 8),
                Expanded(
                  child: PrimaryButton(
                    label: S.of(context)!.ok,
                    onPressed: () async {
                      try {
                        await ref
                            .read(secureStoreProvider)
                            .delete(key: kDuressPinKey);
                      } catch (e, s) {
                        Logging.instance.f(
                          "dpin delete failed!!",
                          error: e,
                          stackTrace: s,
                        );
                      }

                      if (context.mounted) {
                        Navigator.of(context).pop();
                      }
                    },
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );

    ref.read(prefsChangeNotifierProvider).hasDuressPin = false;
  }

